-- Read-only administrative projections. No tokens, arbitrary metadata or audit payloads.
create schema if not exists tamoon_admin;
revoke all on schema tamoon_admin from public,anon;
grant usage on schema tamoon_admin to authenticated;
create view tamoon_admin.partners as select p.id::text id,p.trade_name title,p.responsible_name subtitle,p.status::text status,p.created_at,array[p.id] related_ids,jsonb_build_object('Responsável',p.responsible_name,'E-mail',p.email,'Cidade',p.city,'Contrato',p.contract_status,'Dados bancários',p.banking_status,'Termos',p.terms_status,'Comissão (%)',p.commission_rate,'Reservas',(select count(*) from public.reservations r where r.partner_id=p.id)) details from public.partners p;
revoke all on tamoon_admin.partners from public,anon,authenticated;
create view tamoon_admin.reservations as select r.id::text id,r.public_code title,concat_ws(' · ',p.trade_name,u.display_name) subtitle,r.status::text status,r.created_at,array[r.partner_id,r.user_id] related_ids,jsonb_build_object('Código',r.public_code,'Parceiro',p.trade_name,'Usuário',u.display_name,'Modalidade',r.booking_mode,'Valor bruto',r.gross_value,'Desconto voucher',r.voucher_discount,'Valor líquido',r.net_value,'Pagamento devido',r.payment_due,'Estado financeiro',r.financial_state,'Confirmada em',r.confirmed_at,'Cancelada em',r.cancelled_at) details from public.reservations r left join public.partners p on p.id=r.partner_id left join public.profiles u on u.id=r.user_id;
revoke all on tamoon_admin.reservations from public,anon,authenticated;
create view tamoon_admin.payments as select x.id::text id,coalesce(r.public_code,'Pagamento sem reserva') title,p.trade_name subtitle,x.status::text status,x.created_at,array[x.reservation_id,r.partner_id,r.user_id] related_ids,jsonb_build_object('Reserva',r.public_code,'Provedor',x.provider,'Canal',x.payment_channel,'Valor',x.amount,'Taxa',x.fee_amount,'Líquido',x.net_amount,'Devolvido',x.refunded_amount,'Pago em',x.paid_at,'Disponibilidade',x.cash_availability,'Referência do provedor',x.provider_transaction_id) details from public.payments x left join public.reservations r on r.id=x.reservation_id left join public.partners p on p.id=r.partner_id;
revoke all on tamoon_admin.payments from public,anon,authenticated;
create view tamoon_admin.monthly as select l.id::text id,coalesce(u.display_name,'Cliente não identificado') title,p.trade_name subtitle,l.status,l.created_at,array[l.partner_id,l.customer_profile_id] related_ids,jsonb_build_object('Cliente',u.display_name,'E-mail',u.email,'Parceiro',p.trade_name,'Mensalidade',l.monthly_price,'Dia da semana (0=domingo)',l.weekday,'Início',l.start_time,'Fim',l.end_time,'Vigência inicial',l.start_month,'Vigência final',l.end_month,'Aceite',l.accepted_at,'Ciclos',(select count(*) from public.monthly_cycles c where c.monthly_link_id=l.id)) details from public.monthly_customer_links l left join public.partners p on p.id=l.partner_id left join public.profiles u on u.id=l.customer_profile_id;
revoke all on tamoon_admin.monthly from public,anon,authenticated;
create view tamoon_admin.cycles as select c.id::text id,concat('Mensalidade ',c.service_month) title,concat_ws(' · ',p.trade_name,u.display_name) subtitle,c.status,c.created_at,array[c.monthly_link_id,l.partner_id,l.customer_profile_id,c.reservation_id] related_ids,jsonb_build_object('Mês de referência',c.service_month,'Mensalidade',c.monthly_total,'Total pago',c.total_paid,'Garantia necessária',c.guarantee_required,'Garantia paga',c.guarantee_paid,'Vencimento inicial',c.initial_due_at,'Vencimento saldo',c.balance_due_at,'Reserva ID',c.reservation_id,'Quantidade de datas',c.occurrence_count) details from public.monthly_cycles c join public.monthly_customer_links l on l.id=c.monthly_link_id left join public.partners p on p.id=l.partner_id left join public.profiles u on u.id=l.customer_profile_id;
revoke all on tamoon_admin.cycles from public,anon,authenticated;
create view tamoon_admin.audit as select a.id::text id,concat(a.schema_name,'.',a.table_name) title,coalesce(p.display_name,'Sistema / autor não registrado') subtitle,a.action::text status,a.created_at,array[a.actor_user_id] related_ids,jsonb_build_object('Tabela',concat(a.schema_name,'.',a.table_name),'Registro',a.row_id,'Autor',p.display_name,'Autor ID',a.actor_user_id,'Ação',a.action,'Campos alterados',(select coalesce(string_agg(k,', ' order by k),'Nenhum') from jsonb_object_keys(coalesce(a.old_data,'{}')||coalesce(a.new_data,'{}')) k where (a.old_data->k) is distinct from (a.new_data->k))) details from audit.audit_logs a left join public.profiles p on p.id=a.actor_user_id;
revoke all on tamoon_admin.audit from public,anon,authenticated;

create function tamoon_admin.directory(p_section text,p_search text,p_status text,p_from timestamptz,p_to timestamptz,p_scope uuid,p_page integer,p_size integer,p_id text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_total bigint;v_rows jsonb;v_statuses jsonb;v_sql text;
begin
 if auth.uid() is null or not (exists(select 1 from public.platform_admins a join public.profiles p on p.id=a.profile_id join auth.users u on u.id=p.id where a.profile_id=auth.uid() and p.status::text='active')) then raise sqlstate '42501' using message='Acesso restrito à administração.';end if;
 if p_section is null or p_section not in ('partners','reservations','payments','monthly','cycles','audit') then raise exception 'INVALID_SECTION';end if;
 if p_page is null or p_page<1 or p_size is null or p_size<1 or p_size>50 or char_length(coalesce(p_search,''))>120 or (p_from is not null and p_to is not null and p_to<=p_from) then raise exception 'INVALID_FILTERS';end if;
 -- Whitelist and identifier quoting; search terms remain bound literal values.
 v_sql:=format(' from tamoon_admin.%I where ($1='''' or strpos(lower(coalesce(title,'''')||'' ''||coalesce(subtitle,'''')||'' ''||id||'' ''||details::text),lower($1))>0) and ($2 is null or status=$2) and ($3 is null or created_at>=$3) and ($4 is null or created_at<$4) and ($5 is null or $5=any(related_ids)) and ($6 is null or id=$6)',p_section);
 execute 'select count(*)'||v_sql into v_total using coalesce(p_search,''),p_status,p_from,p_to,p_scope,p_id;
 execute 'select coalesce(jsonb_agg(row_data),''[]''::jsonb) from (select jsonb_build_object(''id'',id,''title'',title,''subtitle'',subtitle,''status'',status,''created_at'',created_at,''details'',details) row_data'||v_sql||' order by created_at desc nulls last,id limit $7 offset $8) q' into v_rows using coalesce(p_search,''),p_status,p_from,p_to,p_scope,p_id,p_size,(p_page::bigint-1)*p_size;
 execute 'select coalesce(jsonb_object_agg(status,n),''{}''::jsonb) from (select coalesce(status,''unknown'') status,count(*) n'||v_sql||' group by status) q' into v_statuses using coalesce(p_search,''),null::text,p_from,p_to,p_scope,p_id;
 return jsonb_build_object('items',v_rows,'total',v_total,'statuses',v_statuses,'page',p_page,'size',p_size,'checked_at',now());
end $$;
revoke all on function tamoon_admin.directory(text,text,text,timestamptz,timestamptz,uuid,integer,integer,text) from public,anon;
grant execute on function tamoon_admin.directory(text,text,text,timestamptz,timestamptz,uuid,integer,integer,text) to authenticated;
create function public.admin_operations_directory(p_section text,p_search text default '',p_status text default null,p_from timestamptz default null,p_to timestamptz default null,p_scope uuid default null,p_page integer default 1,p_size integer default 20,p_id text default null)
returns jsonb language sql stable security invoker set search_path='' as $$ select tamoon_admin.directory(p_section,p_search,p_status,p_from,p_to,p_scope,p_page,p_size,p_id);$$;
revoke all on function public.admin_operations_directory(text,text,text,timestamptz,timestamptz,uuid,integer,integer,text) from public,anon;
grant execute on function public.admin_operations_directory(text,text,text,timestamptz,timestamptz,uuid,integer,integer,text) to authenticated;
